using System;
using System.Linq;
using System.Text.Json;
using CelestialMaker.Core;
using BreakInfinity;
partial class Program {
 static void ReadabilityTests(){
  Check("funding fraction stays finite at astronomical balances",Math.Abs(Simulation.PurchaseFunding(BigDouble.Parse("5e10000"),BigDouble.Parse("1e10001"))-.5)<1e-12);
  Check("funding clamps missing excess and invalid prices",Simulation.PurchaseFunding(-1,200)==0&&Simulation.PurchaseFunding(300,200)==1&&Simulation.PurchaseFunding(20,0)==0);
  foreach(int stage in Enumerable.Range(0,6)){
   var research=data.research.Where(x=>x.stage==stage).ToArray();var upgrades=data.upgrades.Where(x=>x.stage==stage).ToArray();var buildings=data.generators.Where(x=>x.stage==stage).ToArray();
   Check("chapter "+stage+" has strictly increasing research prices",research.Zip(research.Skip(1),(a,b)=>BigDouble.Parse(a.cost)<BigDouble.Parse(b.cost)).All(x=>x));
   Check("chapter "+stage+" has strictly increasing upgrade and building prices",upgrades.Zip(upgrades.Skip(1),(a,b)=>BigDouble.Parse(a.cost)<BigDouble.Parse(b.cost)).All(x=>x)&&buildings.Zip(buildings.Skip(1),(a,b)=>BigDouble.Parse(a.cost)<BigDouble.Parse(b.cost)).All(x=>x));
   Check("chapter "+stage+" upgrades affect its own processes",upgrades.All(u=>data.generators[u.target].stage==stage));
  }
  var previous=new State();previous.purchases.AddRange(new[]{"u4","u8","r0"});previous.owned[1]=7;previous.resources[0]=new BigDouble(123);var previousLoaded=new Simulation(data,Clone(previous));Check("repricing preserves paid IDs stock and owned buildings",previousLoaded.S.purchases.Contains("u4")&&previousLoaded.S.purchases.Contains("u8")&&previousLoaded.S.owned[1]==7&&previousLoaded.S.resources[0].Value==123);
  var u=data.research[0];var second=data.research.First(x=>x.requires==u.id);
  var early=new Simulation(data);early.RefreshRates();Check("research ETA measures missing stock over current net",Math.Abs(early.PurchaseEta(u)-(BigDouble.Parse(u.cost)-early.S.resources[u.costResource].Value).ToDouble()/early.CachedRate(u.costResource).ToDouble())<.001);
  early.S.owned[0]=0;early.RefreshRates();Check("zero production has no finite ETA",double.IsPositiveInfinity(early.PurchaseEta(u)));Check("missing prerequisite has no finite ETA",double.IsPositiveInfinity(early.PurchaseEta(second)));
  early.S.resources[u.costResource]=BigDouble.Parse(u.cost);Check("exact cost is ready",early.CanResearch(u)&&early.PurchaseEta(u)==0);
  var preview=Mature();string before=JsonSerializer.Serialize(preview.S,J);var rates=preview.PreviewRates(preview.Meta.laws,preview.Meta.ascensionUpgrades,purchase:u);var actual=new Simulation(data,Clone(preview.S));actual.Purchase(u);actual.RefreshRates();Check("purchase preview leaves authoritative state identical",before==JsonSerializer.Serialize(preview.S,J));Check("purchase preview matches actual engine rates",Enumerable.Range(0,12).All(i=>Near(rates[i].Value,actual.CachedRate(i))));
  var q=new Simulation(data);q.S.automation.buy=false;Check("queue includes prerequisite in order",q.QueueResearch(second.id)&&q.S.researchPlan.queue.SequenceEqual(new[]{u.id,second.id}));Check("duplicate queue does not duplicate work",!q.QueueResearch(second.id)&&q.S.researchPlan.queue.Count==2);Check("queue rejects upgrades and unknown IDs",!q.QueueResearch(data.upgrades[0].id)&&!q.QueueResearch("missing"));Check("cannot move dependent before prerequisite",!q.MoveQueuedResearch(second.id,-1));q.RemoveQueuedResearch(u.id);Check("removing prerequisite removes dependants",q.S.researchPlan.queue.Count==0);
  q.QueueResearch(second.id);q.S.resources[0]=new BigDouble(1e8);q.S.researchPlan.automatic=true;Advance(q,120);Check("queue cannot bypass Time research unlock",q.S.purchases.Count==0&&q.S.researchPlan.queue.Count==2);
  var ready=Mature();ready.Meta.ascensionUpgrades.AddRange(new[]{"a_time_1","a_time_2"});ready.QueueResearch(second.id);ready.S.researchPlan.automatic=true;ready.S.reserves[0]=BigDouble.Parse("1e100");Advance(ready,60);Check("automatic research queue respects reserves",!ready.S.purchases.Contains(u.id)&&ready.S.researchPlan.queue.Count==2);ready.S.reserves[0]=BigDouble.Zero;Advance(ready,60);Check("unblocked queue executes in dependency order",ready.S.purchases.Contains(second.id)&&ready.S.researchPlan.queue.Count==0);
  var manual=Mature();manual.QueueResearch(u.id);manual.Purchase(u);Check("manual acquisition removes queued item",manual.S.researchPlan.queue.Count==0);
  var offline=Mature();offline.Meta.ascensionUpgrades.AddRange(new[]{"a_time_1","a_time_2"});offline.QueueResearch(second.id);offline.S.researchPlan.automatic=true;offline.S.resources[0]=new BigDouble(1000);var online=new Simulation(data,Clone(offline.S));for(int secondTick=0;secondTick<180;secondTick++)Advance(online,1);offline.BeginOffline(180);while(offline.S.offlineRemaining>0)offline.ProcessOffline(128);Check("queue offline and online produce same purchases and balance",online.S.purchases.SequenceEqual(offline.S.purchases)&&Enumerable.Range(0,12).All(i=>Near(online.S.resources[i].Value,offline.S.resources[i].Value)));
  var due=Mature();due.Meta.ascensionUpgrades.AddRange(new[]{"a_time_1","a_time_2"});due.QueueResearch(u.id);due.S.researchPlan.automatic=true;Advance(due,59);Check("queue waits for its automation decision",!due.S.purchases.Contains(u.id));Advance(due,1);Check("queue executes at its decision with other rules off",due.S.purchases.Contains(u.id));
  var parallelTiming=Mature();parallelTiming.Meta.ascensionUpgrades.AddRange(new[]{"a_time_1","a_time_2"});parallelTiming.Meta.megas[2].level=1;parallelTiming.CreateUniverse(1);parallelTiming.EditUniverse(1,e=>{e.S.automation.buy=false;e.S.resources[0]=new BigDouble(1000);e.QueueResearch(second.id);e.S.researchPlan.automatic=true;});var fine=new Simulation(data,Clone(parallelTiming.S));for(int t=0;t<180;t++)Advance(fine,1);parallelTiming.BeginOffline(180);while(parallelTiming.S.offlineRemaining>0)parallelTiming.ProcessOffline(128);fine.SettleUniverses();parallelTiming.SettleUniverses();Check("parallel queue offline matches small-step simulation",fine.Universe(1).S.purchases.SequenceEqual(parallelTiming.Universe(1).S.purchases)&&Near(fine.Universe(1).S.resources[0].Value,parallelTiming.Universe(1).S.resources[0].Value));
  var migrated=new State{researchPlan=null};migrated.settings.observatory=null;var restored=new Simulation(data,migrated);Check("pre-2.4 saves get passive defaults",restored.S.researchPlan!=null&&!restored.S.researchPlan.automatic&&restored.S.settings.observatory.productionStage==-1);
  var saved=ready.S.settings.observatory;saved.favorites.Add(u.id);saved.goal=second.id;saved.researchFilter=1;saved.upgradeFilter=2;saved.researchSearch="Quantum";ready.QueueResearch(data.research.First(x=>!ready.S.purchases.Contains(x.id)).id);var round=new Simulation(data,Clone(ready.S));Check("filters goal favorites and queue survive serialization",round.S.settings.observatory.favorites.Contains(u.id)&&round.S.settings.observatory.goal==second.id&&round.S.settings.observatory.upgradeFilter==2&&round.S.settings.observatory.researchSearch=="Quantum"&&round.S.researchPlan.queue.SequenceEqual(ready.S.researchPlan.queue));
  var reset=Mature();reset.QueueResearch(second.id);reset.S.researchPlan.automatic=true;reset.Rebirth(1);Check("major reset retains pending plan and pauses spending",reset.S.researchPlan.queue.Count==2&&!reset.S.researchPlan.automatic);
  var resume=Mature();resume.Purchase(u);resume.QueueResearch(second.id);resume.Rebirth(1);Check("reset restores prerequisites already bought before reset",resume.S.researchPlan.queue.SequenceEqual(new[]{u.id,second.id}));
  var parallel=Mature();parallel.Meta.megas[2].level=1;parallel.CreateUniverse(1);parallel.EditUniverse(1,e=>e.QueueResearch(second.id));Check("parallel research plan is isolated",parallel.S.researchPlan.queue.Count==0&&parallel.Universe(1).S.researchPlan.queue.Count==2);var parallelRound=new Simulation(data,Clone(parallel.S));Check("parallel queue survives load",parallelRound.Universe(1).S.researchPlan.queue.SequenceEqual(new[]{u.id,second.id}));parallel.Rebirth(1);Check("parallel reset retains paused plan",parallel.Universe(1).S.researchPlan.queue.Count==2&&!parallel.Universe(1).S.researchPlan.automatic);
  var invalid=new State();invalid.researchPlan.queue.Add("not-content");bool rejected=false;try{new Simulation(data,invalid);}catch(ArgumentException){rejected=true;}Check("unknown queue entry rejected during import",rejected);
 }
}
